<script setup lang="ts">defineProps<{modelValue?:string;options:Array<{label:string;value:string}>}>();defineEmits<{(e:"update:modelValue",value:string):void}>();</script><template><select class="acme-select" :value="modelValue" @change="$emit('update:modelValue',($event.target as HTMLSelectElement).value)"><option v-for="option in options" :key="option.value" :value="option.value">{{option.label}}</option></select></template>